cd /tmp/pscan && timeout 200 osv-scanner scan -L requirements.txt --format json > osv.json 2>/dev/null; python3 - <<'EOF'
import json
d=json.load(open('/tmp/pscan/osv.json'))
for r in d['results']:
  for p in r['packages']:
    pk=p['package']; fixes=set()
    for v in p['vulnerabilities']:
      for a in v.get('affected',[]):
        if a['package']['name'].lower()!=pk['name'].lower(): continue
        for rg in a.get('ranges',[]):
          for e in rg.get('events',[]):
            if 'fixed' in e: fixes.add(e['fixed'])
    ids=[g['ids'][0] for g in p.get('groups',[])]
    print(pk['name'],pk['version'],len(ids),'fixes:',sorted(fixes))
EOF

